package main

import (
	"encoding/binary"
	"testing"
)

// The device handle in the Raw Input header tells physical input (non-zero)
// from input generated by software such as SendInput (zero).
func TestRawDeviceHandle(t *testing.T) {
	for _, hdr := range []int{24, 16} {
		b := rawMouseBuf(hdr, 0, 0, 0, 5, 5)
		if r, ok := parseRaw(b, hdr); !ok || r.Device != 0 {
			t.Fatalf("hdr=%d software input: %+v", hdr, r)
		}
		if hdr == 24 {
			binary.LittleEndian.PutUint64(b[8:], 0x0000000000010ABC)
		} else {
			binary.LittleEndian.PutUint32(b[8:], 0x00010ABC)
		}
		r, ok := parseRaw(b, hdr)
		if !ok || r.Device != 0x10ABC || r.DX != 5 {
			t.Fatalf("hdr=%d physical input: %+v", hdr, r)
		}
	}
}
